WITH valid AS (SELECT *, DAY(txn_time) AS txn_time_day FROM transactions WHERE is_flagged), deduped AS (SELECT * FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY txn_type, merchant ORDER BY txn_time_day, id) = 1), metrics AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, SUM(amount) OVER (PARTITION BY merchant ORDER BY txn_time_day, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, SUM(txn_time_day) OVER (PARTITION BY YEAR(txn_time), account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_txn_time_day, NTILE(5) OVER (PARTITION BY MONTH(txn_time), merchant ORDER BY amount, id) AS amount_bucket, CUME_DIST() OVER w_hist AS amount_cume_dist FROM deduped WHERE txn_time < '2023-11-13' WINDOW w_hist AS (PARTITION BY txn_type ORDER BY amount DESC)), filtered AS (SELECT *, ROUND(amount_cume_dist / running_amount, 2) AS amount_cume_dist_per_running_amount FROM metrics WHERE txn_time >= TO_DATE('2023-06-10')) SELECT id, merchant, measure, val FROM (SELECT id, merchant, amount, amount_cume_dist_per_running_amount, amount_cume_dist FROM filtered) src UNPIVOT (val FOR measure IN (amount, amount_cume_dist_per_running_amount, amount_cume_dist))
